  function save(){try{localStorage.setItem("my-fridge-state",JSON.stringify(state));}catch(e){}}
  function encode(value){const bytes=new TextEncoder().encode(JSON.stringify(value));let binary="";bytes.forEach(b=>binary+=String.fromCharCode(b));return btoa(binary).replace(/\+/g,"-").replace(/\//g,"_").replace(/=+$/g,"");}
  function decode(value){try{const raw=atob(value.replace(/-/g,"+").replace(/_/g,"/"));return JSON.parse(new TextDecoder().decode(Uint8Array.from(raw,c=>c.charCodeAt(0))));}catch(e){return null;}}
  function toast(text){const el=$("toast");el.textContent=text;el.classList.add("show");clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove("show"),2100);}
  function lighten(hex){const n=parseInt(hex.slice(1),16);return "rgb("+Math.min(255,((n>>16)&255)+48)+","+Math.min(255,((n>>8)&255)+48)+","+Math.min(255,(n&255)+48)+")";}
  function darken(hex){const n=parseInt(hex.slice(1),16);return "rgb("+Math.max(0,((n>>16)&255)-38)+","+Math.max(0,((n>>8)&255)-38)+","+Math.max(0,(n&255)-38)+")";}
  function add(type,data){const m={id:uid(),type:type,x:32+Math.random()*38,y:21+Math.random()*53,rotation:(Math.random()*8-4).toFixed(1),size:.8,action:"none",url:"",urls:[],memo:"",title:"",...data};state.magnets.push(m);selectedId=null;render();save();}
  function current(){return state.magnets.find(m=>m.id===selectedId);}
