      if(m.type==="souvenir")art.innerHTML='<span class="souvenir-icon">'+escapeHTML(m.icon||"✈️")+'</span><strong>'+escapeHTML(m.title||"TRAVEL")+'</strong><small>'+escapeHTML(m.caption||"A LITTLE MEMORY")+'</small>';
      el.appendChild(art);
      if(visitorMode)el.addEventListener("click",e=>{e.stopPropagation();openVisitor(m);});
