      const rotate=document.createElement("button");rotate.className="magnet-control";rotate.type="button";rotate.textContent="↻";rotate.title="드래그해서 회전";rotate.setAttribute("aria-label","회전 손잡이를 드래그해 마그넷 기울이기");rotate.addEventListener("pointerdown",e=>rotateStart(e,chosen));
